package dev.pocketengine.browser;

import java.util.Set;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class BrowserFrameReadRegistryTest {
    static final String TOP="https://top.example",CHILD="https://embed.example",TOKEN="a".repeat(32),NEXT="b".repeat(32);
    static BrowserFrameReadRegistry<Object> registry()throws Exception {BrowserFrameReadRegistry<Object> r=new BrowserFrameReadRegistry<>();r.reset(UUID.randomUUID().toString(),"native-registration",TOP,Set.of(TOP,CHILD));return r;}
    @Test public void onlyActualNativeOriginAndCurrentRegistrationCanRegister()throws Exception {var r=registry();assertFalse(r.register(new Object(),"https://unknown.example",false,"native-registration",TOKEN));assertFalse(r.register(new Object(),CHILD,true,"native-registration",TOKEN));assertFalse(r.register(new Object(),CHILD,false,"old-registration",TOKEN));assertFalse(r.register(new Object(),CHILD,false,"native-registration","page-content"));assertTrue(r.frames().isEmpty());}
    @Test public void registrationDoesNotGrantAHiddenFrameRead()throws Exception {var r=registry();r.register(new Object(),CHILD,false,"native-registration",TOKEN);String id=r.frames().get(0).id;assertThrows(SecurityException.class,()->r.requirePresentedChild(id,1));}
    @Test public void onlyFinalPresentedFrameFactsCanBecomeKnown()throws Exception {var r=registry();r.register(new Object(),CHILD,false,"native-registration",TOKEN);var frame=r.frames().get(0);var candidates=r.candidates();r.presented(r.catalogue(null),candidates,10);assertSame(frame,r.requirePresentedChild(frame.id,11));JSONObject forged=frame.facts(false).put("sourceOrigin",TOP);assertThrows(SecurityException.class,()->r.presented(new JSONArray().put(forged),candidates,12));}
    @Test public void sameProxyNavigatingToNewDocumentNeverRetargetsAnOldFrameRef()throws Exception {var r=registry();Object proxy=new Object();r.register(proxy,CHILD,false,"native-registration",TOKEN);var old=r.frames().get(0);r.presented(r.catalogue(null),r.candidates(),10);r.register(proxy,CHILD,false,"native-registration",NEXT);var fresh=r.frames().get(0);assertNotEquals(old.id,fresh.id);assertNotEquals(old.document,fresh.document);assertFalse(r.current(old));assertThrows(SecurityException.class,()->r.requirePresentedChild(old.id,11));assertThrows(SecurityException.class,()->r.requirePresentedChild(fresh.id,11));}
    @Test public void oldCallbackCannotRetireReplacementAndOldPendingProjectionCannotPresentIt()throws Exception {var r=registry();Object proxy=new Object();r.register(proxy,CHILD,false,"native-registration",TOKEN);var old=r.frames().get(0);var candidates=r.candidates();JSONArray shown=r.catalogue(null);r.register(proxy,CHILD,false,"native-registration",NEXT);var fresh=r.frames().get(0);r.retire(old);assertTrue(r.current(fresh));assertThrows(SecurityException.class,()->r.presented(shown,candidates,12));}
    @Test public void topDocumentOrProfileResetRetiresAllChildRefs()throws Exception {var r=registry();r.register(new Object(),CHILD,false,"native-registration",TOKEN);var old=r.frames().get(0);r.presented(r.catalogue(null),r.candidates(),10);r.reset(UUID.randomUUID().toString(),"new-registration",TOP,Set.of(TOP));assertThrows(SecurityException.class,()->r.requirePresentedChild(old.id,11));assertFalse(r.register(new Object(),CHILD,false,"new-registration",TOKEN));}
    @Test public void lateFramesRequireTheirOwnActuallyDeliveredCatalogueAndRefsExpire()throws Exception {var r=registry();r.register(new Object(),TOP,true,"native-registration",TOKEN);var first=r.candidates();JSONArray firstShown=r.catalogue(null);r.register(new Object(),CHILD,false,"native-registration",TOKEN);var child=r.frames().get(1);r.presented(firstShown,first,10);assertThrows(SecurityException.class,()->r.requirePresentedChild(child.id,11));r.presented(r.catalogue(null),r.candidates(),20);assertSame(child,r.requirePresentedChild(child.id,21));assertThrows(SecurityException.class,()->r.requirePresentedChild(child.id,20+BrowserFrameReadRegistry.REF_LIMIT_MS+1));}
    @Test public void frameMapIsBoundedAndDuplicateHandshakeDoesNotReassignIdentity()throws Exception {var r=registry();Object original=new Object();r.register(original,CHILD,false,"native-registration",TOKEN);String first=r.frames().get(0).id;assertTrue(r.register(original,CHILD,false,"native-registration",TOKEN));assertEquals(first,r.frames().get(0).id);for(int i=1;i<BrowserFrameReadRegistry.MAX_FRAMES;i++)assertTrue(r.register(new Object(),CHILD,false,"native-registration",TOKEN));assertFalse(r.register(new Object(),CHILD,false,"native-registration",TOKEN));assertEquals(BrowserFrameReadRegistry.MAX_FRAMES,r.frames().size());}
}
